// src/procedural.ts  -- Chapter 1 ka poora parking lot

type Size = "small" | "medium" | "large";

// ── DATA (sab upar, sabke liye khula) ──
let spots: { id: string; floor: number; size: Size; takenBy: string | null }[] = [
  { id: "F1-S1", floor: 1, size: "small",  takenBy: null },
  { id: "F1-S2", floor: 1, size: "medium", takenBy: null },
  { id: "F2-S1", floor: 2, size: "large",  takenBy: null }
];

let tickets: { id: string; plate: string; spotId: string; inAt: number }[] = [];
let earnings = 0;
let ticketCounter = 0;

// ── FUNCTIONS (sab neeche) ──
function park(plate: string, size: Size): string | null {
  const spot = spots.find(s => s.takenBy === null && s.size === size);
  if (!spot) return null;

  spot.takenBy = plate;
  ticketCounter++;
  const id = "T-" + ticketCounter;
  tickets.push({ id, plate, spotId: spot.id, inAt: Date.now() });
  return id;
}

function unpark(ticketId: string): number {
  const t = tickets.find(x => x.id === ticketId);
  if (!t) return 0;

  const spot = spots.find(s => s.id === t.spotId);
  if (spot) spot.takenBy = null;

  const hours = Math.ceil((Date.now() - t.inAt) / 3600000);
  const rate = spot?.size === "large" ? 40 : spot?.size === "medium" ? 30 : 20;
  const fee = hours * rate;
  earnings += fee;
  return fee;
}

