// src/ParkingLot.ts

class Spot {
  takenBy: string | null = null;

  constructor(
    public id: string,
    public floor: number,
    public size: VehicleSize
  ) {}

  isFree(): boolean {
    return this.takenBy === null;
  }

  fits(size: VehicleSize): boolean {
    return this.isFree() && this.size === size;
  }
}

class Ticket {
  exitedAt: Date | null = null;

  constructor(
    public id: string,
    public plate: string,
    public spotId: string,
    public enteredAt: Date
  ) {}

  hoursParked(now: Date): number {
    const end = this.exitedAt ?? now;
    return Math.ceil((end.getTime() - this.enteredAt.getTime()) / 3600000);
  }
}

class ParkingLot {
  spots: Spot[] = [];
  tickets: Ticket[] = [];
  earnings = 0;
  private counter = 0;                 // ye ek chhota jhaanka hai Chapter 3 ka

  constructor(public name: string) {}

  addSpot(id: string, floor: number, size: VehicleSize): void {
    this.spots.push(new Spot(id, floor, size));
  }

  park(plate: string, size: VehicleSize): Ticket | null {
    const spot = this.spots.find(s => s.fits(size));
    if (!spot) return null;

    spot.takenBy = plate;
    this.counter++;
    const ticket = new Ticket("T-" + this.counter, plate, spot.id, new Date());
    this.tickets.push(ticket);
    return ticket;
  }

  unpark(ticketId: string, now = new Date()): number {
    const t = this.tickets.find(x => x.id === ticketId);
    if (!t || t.exitedAt) return 0;

    const spot = this.spots.find(s => s.id === t.spotId);
    if (!spot) return 0;

    spot.takenBy = null;
    t.exitedAt = now;

    const rate = spot.size === "large" ? 40 : spot.size === "medium" ? 30 : 20;
    const fee = t.hoursParked(now) * rate;
    this.earnings += fee;
    return fee;
  }

  availableCount(size: VehicleSize): number {
    return this.spots.filter(s => s.fits(size)).length;
  }
}

