// 2. Ek object parameter -- 3+ parameters ke liye best
interface LotConfig {
  name: string;
  floors?: number;
  smallSpots?: number;
  largeSpots?: number;
}
class Lot2 {
  constructor(private config: LotConfig) {}
}
new Lot2({ name: "Airport", floors: 5, smallSpots: 100 });
//  ^ padhne mein saaf. new Lot2("Airport", 5, 100, 0) mein
//    koi nahi bata sakta ki 100 kiska hai.

// 3. Static factory -- naam de sakte ho
class Lot3 {
  private constructor(public name: string, public spots: Spot[]) {}

  static empty(name: string): Lot3 {
    return new Lot3(name, []);
  }

  static withFloors(name: string, floors: number, perFloor: number): Lot3 {
    const spots: Spot[] = [];
    for (let f = 1; f <= floors; f++)
      for (let i = 1; i <= perFloor; i++)
        spots.push(new Spot(`F${f}-S${i}`, f, "medium"));
    return new Lot3(name, spots);
  }
}

