class ParkingLot {
  #earnings = 0;
  #spots: Spot[] = [];
  #tickets = new Map<string, Ticket>();
  #counter = 0;

  // INVARIANT 1: earnings kabhi negative nahi
  #collectFee(amount: number): void {
    if (amount < 0) throw new Error("Fee negative nahi ho sakti: " + amount);
    this.#earnings += amount;
  }

  // INVARIANT 2: ek spot mein zyada se zyada ek gaadi
  park(plate: string, size: VehicleSize): Ticket | null {
    // guard clauses -- galat input andar hi nahi aayega
    if (!plate.trim()) throw new Error("Plate khaali nahi ho sakti");

    const already = [...this.#tickets.values()].find(
      t => t.plate === plate && !t.exitedAt
    );
    if (already) throw new Error("Ye gaadi pehle se andar hai: " + plate);

    const spot = this.#spots.find(s => s.isFree() && s.size === size);
    if (!spot) return null;              // <- ye BUG nahi hai, ye normal hai

    spot.occupy(plate);                  // Spot khud apna niyam check karega
    this.#counter++;
    const ticket = new Ticket("T-" + this.#counter, plate, spot.id, new Date());
    this.#tickets.set(ticket.id, ticket);
    return ticket;
  }

  // INVARIANT 3: zinda ticket ki spot bhari honi chahiye
  unpark(ticketId: string, now = new Date()): number {
    const t = this.#tickets.get(ticketId);
    if (!t) throw new Error("Aisa koi ticket nahi: " + ticketId);
    if (t.exitedAt) throw new Error("Ye ticket pehle hi use ho chuka hai");

    const spot = this.#spots.find(s => s.id === t.spotId);
    if (!spot) throw new Error("Ticket ki spot hi nahi mili — data corrupt hai");

    spot.release();
    t.markExit(now);
    const fee = t.hoursParked(now) * this.#rateFor(spot.size);
    this.#collectFee(fee);
    return fee;
  }

  get earnings(): number { return this.#earnings; }
  get freeCount(): number { return this.#spots.filter(s => s.isFree()).length; }
}

// Spot bhi apna niyam khud sambhale:
class Spot {
  #takenBy: string | null = null;

  occupy(plate: string): void {
    if (this.#takenBy) throw new Error(`Spot ${this.id} pehle se bhari hai`);
    this.#takenBy = plate;
  }
  release(): void { this.#takenBy = null; }
  isFree(): boolean { return this.#takenBy === null; }
}
