// ── AB: Error bhi ek class ──
export class ParkingError extends Error {
  constructor(message: string) {
    super(message);
    this.name = new.target.name;
    Object.setPrototypeOf(this, new.target.prototype);   // instanceof ke liye zaroori
  }
}

export class SpotOccupiedError extends ParkingError {
  constructor(public readonly spotId: string, public readonly byPlate: string) {
    super(`Spot ${spotId} pehle se bhari hai (${byPlate})`);
  }
}

export class InvalidPlateError extends ParkingError {
  constructor(public readonly given: string) {
    super(`Plate ka format galat hai: "${given}"`);
  }
}

export class TicketAlreadyUsedError extends ParkingError {
  constructor(public readonly ticketId: string, public readonly exitedAt: Date) {
    super(`Ticket ${ticketId} pehle hi use ho chuka hai`);
  }
}

// Use karo:
class Spot {
  occupy(plate: string): void {
    if (this.#takenBy) throw new SpotOccupiedError(this.id, this.#takenBy);
    this.#takenBy = plate;
