// ── JO CHAHIYE (abstraction ke saath) ──
class ParkingLot {
  unpark(ticketId: string, payment: PaymentMethod): number {
    const fee = this.#calculateFee(ticketId);
    payment.pay(fee);            // <- bas. "Kaise" ka pata hi nahi.
