// Ye "PaymentMethod" cheez kya hai? Agli lesson mein.

// ── INTERFACE: sirf waada, koi code nahi ──
interface PaymentMethod {
  readonly name: string;
  pay(amount: number): PaymentResult;
}

interface PaymentResult {
  success: boolean;
  reference: string;
}

// ── TEEN ALAG TARIKE, EK HI WAADA ──
class CashPayment implements PaymentMethod {
  readonly name = "Cash";
  #drawer = 0;

  pay(amount: number): PaymentResult {
    this.#drawer += amount;
    return { success: true, reference: "CASH-" + Date.now() };
  }
}

class UpiPayment implements PaymentMethod {
  readonly name = "UPI";
  constructor(private vpa: string) {}

  pay(amount: number): PaymentResult {
    const qr = this.#makeQr(amount);
    const ok = this.#waitForConfirm(qr);
