// Implementation 1: array (simple, chhote lot ke liye)
class ArraySpotRepo implements SpotRepository {
  #spots: Spot[] = [];
  findFree(size: VehicleSize) { return this.#spots.find(s => s.isFree() && s.size === size); }
  save(spot: Spot) { this.#spots.push(spot); }
  count() { return this.#spots.length; }
}

// Implementation 2: size ke hisaab se Map (bade lot ke liye tez)
class IndexedSpotRepo implements SpotRepository {
  #bySize = new Map<VehicleSize, Spot[]>();
  findFree(size: VehicleSize) { return this.#bySize.get(size)?.find(s => s.isFree()); }
  save(spot: Spot) {
    const list = this.#bySize.get(spot.size) ?? [];
    list.push(spot);
    this.#bySize.set(spot.size, list);
  }
  count() { return [...this.#bySize.values()].reduce((n, l) => n + l.length, 0); }
}

// Implementation 3: test ke liye nakli (koi asli storage nahi)
class FakeSpotRepo implements SpotRepository {
  constructor(private fake: Spot | undefined) {}
  findFree() { return this.fake; }
  save() {}
  count() { return this.fake ? 1 : 0; }
}

