// ── VERSION 1: sab theek hai ──
class ParkingLot {
  protected spots: Spot[] = [];
  #count = 0;

  park(vehicles: Vehicle[]): number {
    let done = 0;
    for (const v of vehicles) {
      if (this.parkOne(v)) done++;     // <- apni hi method bula rahe hain
    }
    return done;
  }

  protected parkOne(v: Vehicle): boolean {
    const spot = this.spots.find(s => v.canPark(s));
    if (!spot) return false;
    spot.occupy(v.plate);
    this.#count++;
    return true;
  }
}

