// ── CHEEZON KE INTERFACES ──
interface Clock { now(): Date; }
class SystemClock implements Clock { now() { return new Date(); } }

class FakeClock implements Clock {
  constructor(private current: Date) {}
  now() { return this.current; }
  advanceHours(h: number) {
    this.current = new Date(this.current.getTime() + h * 3600000);
  }
}

interface Notifier { send(to: string, msg: string): void; }
class SmsNotifier implements Notifier { send(to: string, msg: string) { /* asli API */ } }
class FakeNotifier implements Notifier {
  public sent: string[] = [];
  send(to: string, msg: string) { this.sent.push(`${to}: ${msg}`); }
}


// ── ParkingLot ab kuch NAHI banati ──
class ParkingLot {
  constructor(
    private spots: SpotRepository,
    private pricing: PricingPolicy,
    private clock: Clock,
    private notifier: Notifier
  ) {}

  unpark(ticketId: string, payment: PaymentMethod): number {
    const t = this.#tickets.get(ticketId)!;
    const now = this.clock.now();                    // ✓ inject kiya hua waqt
    const fee = this.pricing.calculate(t, now);
    payment.pay(fee);
    this.notifier.send(t.plate, `Fee: ₹${fee}`);
    return fee;
  }
}


