// ── AUR EK VALUE OBJECT: PlateNumber ──
class PlateNumber {
  readonly #value: string;
  private constructor(v: string) { this.#value = v; }

  static parse(raw: string): PlateNumber {
    const clean = raw.trim().toUpperCase().replace(/\s+/g, "");
    if (!/^[A-Z]{2}[0-9]{2}[A-Z]{1,2}[0-9]{4}$/.test(clean))
      throw new Error("Plate ka format galat: " + raw);
    return new PlateNumber(clean);
  }

  toString() { return this.#value; }
  equals(o: PlateNumber) { return this.#value === o.#value; }
}
