// ── STRATEGY (tumne 3 baar banaya) ──
interface PricingPolicy {
  calculate(ticket: Ticket, now: Date): Money;
}

class HourlyPricing implements PricingPolicy {
  calculate(t: Ticket, now: Date): Money {
    return Money.rupees(t.hoursParked(now) * 30);
  }
}

class WeekendPricing implements PricingPolicy {
  calculate(t: Ticket, now: Date): Money {
    const isWeekend = [0, 6].includes(now.getDay());
    return Money.rupees(t.hoursParked(now) * (isWeekend ? 45 : 30));
  }
}

class MonthlyPassPricing implements PricingPolicy {
  constructor(private passes: Set<string>) {}
  calculate(t: Ticket, now: Date): Money {
    if (this.passes.has(t.plate)) return Money.zero();
    return Money.rupees(t.hoursParked(now) * 30);
  }
}

