// ── DECORATOR ──
// Har decorator ussi interface ko implement karta hai
class SurgePricing implements PricingPolicy {
  constructor(private inner: PricingPolicy) {}       // <- lapeta hua
  calculate(t: Ticket, now: Date): Money {
    const base = this.inner.calculate(t, now);
    const isPeak = now.getHours() >= 18 && now.getHours() <= 21;
    return isPeak ? base.times(1.5) : base;
  }
}

class LoyaltyDiscount implements PricingPolicy {
  constructor(private inner: PricingPolicy, private members: Set<string>) {}
  calculate(t: Ticket, now: Date): Money {
    const base = this.inner.calculate(t, now);
    return this.members.has(t.plate) ? base.times(0.9) : base;
  }
}

class GstPricing implements PricingPolicy {
  constructor(private inner: PricingPolicy, private rate = 0.18) {}
  calculate(t: Ticket, now: Date): Money {
    return this.inner.calculate(t, now).times(1 + this.rate);
  }
}

