// ── TEMPLATE METHOD ──
abstract class ParkingProcess {
  // TEMPLATE: kram fixed hai, ye method override nahi honi chahiye
  park(v: Vehicle): Ticket | null {
    this.validate(v);                          // step 1 (fixed)
    const spot = this.findSpot(v);             // step 2 (bachcha bharta hai)
    if (!spot) return null;
    spot.occupy(v.plate);                      // step 3 (fixed)
    const ticket = this.createTicket(v, spot); // step 4 (bachcha bhar sakta hai)
    this.afterPark(ticket, v);                 // step 5 (hook, optional)
    return ticket;
  }

  protected validate(v: Vehicle): void {
    if (!v.plate) throw new Error("Plate chahiye");
  }

  protected abstract findSpot(v: Vehicle): Spot | undefined;   // BHARNA ZAROORI

  protected createTicket(v: Vehicle, s: Spot): Ticket {
    return new Ticket(nextId(), v.plate, s.id, this.clock.now());
  }

  protected afterPark(t: Ticket, v: Vehicle): void { }          // HOOK, optional
}

class NearestFirstLot extends ParkingProcess {
  protected findSpot(v: Vehicle) {
    return this.spots.filter(s => s.fits(v.getSize()))
                     .sort((a, b) => a.floor - b.floor)[0];
  }
}

class ValetLot extends ParkingProcess {
  protected findSpot(v: Vehicle) {
    return this.spots.find(s => s.fits(v.getSize()));   // koi bhi
  }
  protected override afterPark(t: Ticket, v: Vehicle) {
    this.valetQueue.add(t.id);                          // hook use kiya
  }
}
