  withValet(): this { this.#valet = true; return this; }
  pricing(p: PricingPolicy): this { this.#pricing = p; return this; }

  build(): ParkingLot {
    // SAARI validation YAHAN -- ek baar, sab jagah ki
    if (!this.#name.trim()) throw new Error("Lot ka naam chahiye");
    if (this.#floors < 1) throw new Error("Kam se kam 1 floor chahiye");
    const total = this.#small + this.#medium + this.#large;
    if (total === 0) throw new Error("Kam se kam ek spot chahiye");
    if (this.#valet && this.#large === 0)
      throw new Error("Valet ke liye large spots chahiye");
    //  ^ ye check kisi ek setter mein LAG HI NAHI SAKTA THA,
    //    kyunki us waqt doosri value abhi aayi hi nahi thi

    const spots = new ArraySpotRepo();
    // ... spots banao
    return new ParkingLot(spots, this.#pricing, new SystemClock(), notifier);
  }
}

