// ADAPTER: beech mein khada hokar tarjuma karta hai
// infra/RazorpayAdapter.ts   <- INFRA mein, domain mein NAHI
export class RazorpayAdapter implements PaymentMethod {
  readonly name = "Razorpay";
  constructor(private client: RazorpayClient) {}

  pay(amount: Money): PaymentResult {
    const order = await this.client.createOrder(amount.paise, "INR");
    //                                          ^ Money -> paise ka tarjuma
    const res = await this.client.capturePayment(order.order_id);
    return {
      success: res.status === "captured",     // library ka jawab -> hamara jawab
      reference: order.order_id
    };
  }
}

