// ✓ Data aur logic ek jagah
class Ticket {
  #exitedAt: Date | null = null;
  constructor(
    public readonly id: string,
    public readonly plate: PlateNumber,
    public readonly enteredAt: Date
  ) {}

  hoursParked(now: Date): number {
    const end = this.#exitedAt ?? now;
    return Math.ceil((end.getTime() - this.enteredAt.getTime()) / 3600000);
  }
  isExpired(now: Date): boolean { return this.hoursParked(now) > 24; }
  markExit(now: Date): void {
    if (this.#exitedAt) throw new Error("Ticket pehle hi use ho chuka hai");
    this.#exitedAt = now;
  }
}


